package za.co.lepetse.admin;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @Transactional
@EnabledIfEnvironmentVariable(named="LEPETSE_DB_TEST",matches="true")
class OpportunityDiscoveryTest {
 @Autowired OpportunityDiscovery service;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired MockMvc http;
 long search(){return db.queryForObject("select min(id) from opportunity_search",Long.class);}
 Map<String,Object> profile(){return Map.of("name","Test stationery","keywords","stationery, pens","exclusions","hardware","criteria","Confirm stock");}
 JsonNode notice(String id,String scope,String end,String date)throws Exception{return json.readTree(json.writeValueAsString(Map.of("ocid",id,"date",date,"buyer",Map.of("name","TEST treasury buyer"),"tender",Map.of("title",id,"description",scope,"tenderPeriod",Map.of("endDate",end),"documents",List.of(Map.of("url","https://example.com/official.pdf"))))));}
 @Test void deduplicatesAndKeepsHumanDecisionAndDescriptions()throws Exception{String id="ocds-test-"+UUID.randomUUID();var first=notice(id,"Office stationery","2099-12-01T09:00:00Z","2026-11-20T00:00:00Z");assertThat(service.ingest(search(),profile(),first)).isEqualTo(1);assertThat(service.ingest(search(),profile(),first)).isZero();long opp=db.queryForObject("select opportunity_id from opportunity_discovery_source where ocid=?",Long.class,id);db.update("update work_opportunity set progress='dismissed',details=jsonb_set(details,'{title}','\"Reviewed title\"') where id=?",opp);assertThat(service.ingest(search(),profile(),notice(id,"Office stationery revised","2099-12-02T09:00:00Z","2026-11-21T00:00:00Z"))).isEqualTo(2);var row=db.queryForMap("select progress,details->>'title' title,change_notice from work_opportunity where id=?",opp);assertThat(row.get("progress")).isEqualTo("dismissed");assertThat(row.get("title")).isEqualTo("Reviewed title");assertThat(row.get("change_notice")).isEqualTo("Closing deadline changed");assertThat(service.ingest(search(),profile(),first)).isZero();assertThat(db.queryForObject("select count(*) from opportunity_search_match where opportunity_id=?",Integer.class,opp)).isEqualTo(1);}
 @Test void skipsUnrelatedExcludedClosedAndUnknownDeadlines()throws Exception{String id="ocds-test-"+UUID.randomUUID();assertThat(service.ingest(search(),profile(),notice(id,"hardware stationery","2099-12-01T09:00:00Z","2026-11-20T00:00:00Z"))).isZero();assertThat(service.ingest(search(),profile(),notice(id,"open procurement","2099-12-01T09:00:00Z","2026-11-20T00:00:00Z"))).isZero();assertThat(service.ingest(search(),profile(),notice(id,"pens","2000-12-01T09:00:00Z","2026-11-20T00:00:00Z"))).isZero();assertThat(service.ingest(search(),profile(),notice(id,"pens","","2026-11-20T00:00:00Z"))).isEqualTo(-1);assertThat(OpportunityDiscovery.terms("open tenders","pen")).isFalse();}
 @Test void newMatchesArePossibleAndUnverifiedNotApproved()throws Exception{String id="ocds-test-"+UUID.randomUUID();service.ingest(search(),profile(),notice(id,"Stationery supply","2099-12-01T09:00:00Z","2026-11-20T00:00:00Z"));var d=json.readTree(db.queryForObject("select details::text from work_opportunity where reference=?",String.class,id));assertThat(d.path("recommendation").asText()).isEqualTo("possible");assertThat(d.path("requirements").asText()).contains("Not verified");assertThat(d.path("email").asText()).isEmpty();}
 @Test void settingsProtectedAndVersioned()throws Exception{http.perform(get("/api/admin/opportunity-searches")).andExpect(status().isUnauthorized());http.perform(post("/api/admin/opportunity-searches/"+search()+"/fetch").with(user("owner").roles("ADMIN"))).andExpect(status().isForbidden());var settings=Map.of("keywords","paper, pens","exclusions","hardware","criteria","Review budget","dailyEnabled",false,"runTime","08:30","version",db.queryForObject("select version from opportunity_search where id=?",Integer.class,search()));String body=json.writeValueAsString(settings);http.perform(put("/api/admin/opportunity-searches/"+search()).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(body)).andExpect(status().isOk());http.perform(put("/api/admin/opportunity-searches/"+search()).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(body)).andExpect(status().isConflict());assertThat(db.queryForObject("select daily_enabled from opportunity_search where id=?",Boolean.class,search())).isFalse();}
 @Test void suppliesWorkspaceHidesAndDisablesNamaro()throws Exception{long archived=db.queryForObject("select id from opportunity_search where name='Namaro IT'",Long.class);http.perform(get("/api/admin/opportunity-searches").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(1)).andExpect(jsonPath("$[0].name").value("Supply opportunities"));http.perform(post("/api/admin/opportunity-searches/"+archived+"/fetch").with(user("owner").roles("ADMIN")).with(csrf())).andExpect(status().isConflict());assertThat(db.queryForObject("select daily_enabled from opportunity_search where id=?",Boolean.class,archived)).isFalse();String terms=db.queryForObject("select keywords from opportunity_search where name='Supply opportunities'",String.class);for(String text:List.of("SUPPLY AND DELIVERY OF TOILET PAPER","Cleaning chemicals for office use","Stationery supplies","Tissues"))assertThat(OpportunityDiscovery.terms(text,terms)).isTrue();String excludes=db.queryForObject("select exclusions from opportunity_search where name='Supply opportunities'",String.class);assertThat(OpportunityDiscovery.terms("Contract for cleaning services",excludes)).isTrue();}
}
